import React, { useState, useEffect } from 'react';
import { getApiBaseUrl } from '../utils/api';
import { Trophy, Medal, DollarSign, Users, TrendingUp, Award, Crown, Star } from 'lucide-react';

interface LeaderboardRecord {
  id: string;
  username: string;
  profile_pic: string | null;
  total_games: number;
  wins: number;
  losses: number;
  ties: number;
  win_percentage: number;
}

interface EarningsRecord {
  id: string;
  username: string;
  profile_pic: string | null;
  money_games_played: number;
  total_earnings: number;
  total_losses: number;
  total_wagered: number;
  win_percentage: number;
}

const Leaderboard: React.FC = () => {
  const [leagueARecords, setLeagueARecords] = useState<LeaderboardRecord[]>([]);
  const [leagueBRecords, setLeagueBRecords] = useState<LeaderboardRecord[]>([]);
  const [earningsRecords, setEarningsRecords] = useState<EarningsRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [activeTab, setActiveTab] = useState<'leagueA' | 'leagueB' | 'earnings'>('leagueA');

  useEffect(() => {
    fetchLeaderboardData();
  }, []);

  const fetchLeaderboardData = async () => {
    try {
      setLoading(true);
      const apiBaseUrl = getApiBaseUrl();

      // Fetch all leaderboard data in parallel
      const [leagueAResponse, leagueBResponse, earningsResponse] = await Promise.all([
        fetch(`${apiBaseUrl}/api/leaderboard/records?league=A`),
        fetch(`${apiBaseUrl}/api/leaderboard/records?league=B`),
        fetch(`${apiBaseUrl}/api/leaderboard/earnings`)
      ]);

      if (leagueAResponse.ok) {
        const data = await leagueAResponse.json();
        setLeagueARecords(data);
      }

      if (leagueBResponse.ok) {
        const data = await leagueBResponse.json();
        setLeagueBRecords(data);
      }

      if (earningsResponse.ok) {
        const data = await earningsResponse.json();
        setEarningsRecords(data);
      }

    } catch (error) {
      console.error('Error fetching leaderboard data:', error);
      setError('Failed to load leaderboard data');
    } finally {
      setLoading(false);
    }
  };

  const getRankIcon = (index: number) => {
    switch (index) {
      case 0:
        return <Crown className="w-6 h-6 text-yellow-500" />;
      case 1:
        return <Medal className="w-6 h-6 text-gray-400" />;
      case 2:
        return <Award className="w-6 h-6 text-amber-600" />;
      default:
        return <span className="w-6 h-6 flex items-center justify-center text-gray-500 font-bold">
          {index + 1}
        </span>;
    }
  };

  const getRankColor = (index: number) => {
    switch (index) {
      case 0:
        return 'bg-gradient-to-r from-yellow-400 to-yellow-600 text-white';
      case 1:
        return 'bg-gradient-to-r from-gray-300 to-gray-500 text-white';
      case 2:
        return 'bg-gradient-to-r from-amber-500 to-amber-700 text-white';
      default:
        return 'bg-white border border-gray-200';
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="max-w-6xl mx-auto p-6">
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-md">
          {error}
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-6xl mx-auto p-6">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900 flex items-center mb-2">
          <Trophy className="w-8 h-8 mr-3 text-yellow-500" />
          Leaderboard
        </h1>
        <p className="text-gray-600">Top performers across all sports and money games</p>
      </div>

      {/* Tab Navigation */}
      <div className="mb-8">
        <div className="border-b border-gray-200">
          <nav className="-mb-px flex space-x-8">
            <button
              onClick={() => setActiveTab('leagueA')}
              className={`py-2 px-1 border-b-2 font-medium text-sm ${
                activeTab === 'leagueA'
                  ? 'border-blue-500 text-blue-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
              }`}
            >
              <div className="flex items-center">
                <Star className="w-4 h-4 mr-2" />
                League A Records
              </div>
            </button>
            <button
              onClick={() => setActiveTab('leagueB')}
              className={`py-2 px-1 border-b-2 font-medium text-sm ${
                activeTab === 'leagueB'
                  ? 'border-blue-500 text-blue-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
              }`}
            >
              <div className="flex items-center">
                <Star className="w-4 h-4 mr-2" />
                League B Records
              </div>
            </button>
            <button
              onClick={() => setActiveTab('earnings')}
              className={`py-2 px-1 border-b-2 font-medium text-sm ${
                activeTab === 'earnings'
                  ? 'border-blue-500 text-blue-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
              }`}
            >
              <div className="flex items-center">
                <DollarSign className="w-4 h-4 mr-2" />
                Money Games Earnings
              </div>
            </button>
          </nav>
        </div>
      </div>

      {/* League A Records */}
      {activeTab === 'leagueA' && (
        <div className="bg-white rounded-lg shadow-lg overflow-hidden">
          <div className="px-6 py-4 bg-gradient-to-r from-blue-500 to-blue-600 text-white">
            <h2 className="text-xl font-semibold flex items-center">
              <Star className="w-5 h-5 mr-2" />
              League A - Best Records
            </h2>
            <p className="text-blue-100 text-sm">Top performers in competitive League A games</p>
          </div>

          {leagueARecords.length === 0 ? (
            <div className="p-8 text-center text-gray-500">
              <Trophy className="mx-auto h-12 w-12 text-gray-400 mb-4" />
              <p>No League A records yet</p>
              <p className="text-sm">Complete some League A games to appear on the leaderboard</p>
            </div>
          ) : (
            <div className="divide-y divide-gray-200">
              {leagueARecords.map((record, index) => (
                <div key={record.id} className={`p-6 ${getRankColor(index)}`}>
                  <div className="flex items-center justify-between">
                    <div className="flex items-center space-x-4">
                      {getRankIcon(index)}
                      <div className="w-12 h-12 bg-gray-200 rounded-full flex items-center justify-center">
                        {record.profile_pic ? (
                          <img 
                            src={record.profile_pic} 
                            alt={record.username} 
                            className="w-12 h-12 rounded-full object-cover"
                          />
                        ) : (
                          <Users className="w-6 h-6 text-gray-400" />
                        )}
                      </div>
                      <div>
                        <h3 className="text-lg font-semibold">{record.username}</h3>
                        <div className="flex items-center space-x-4 text-sm opacity-90">
                          <span>{record.total_games} games</span>
                          <span>{record.wins}W - {record.losses}L - {record.ties}T</span>
                        </div>
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="text-2xl font-bold">{record.win_percentage}%</div>
                      <div className="text-sm opacity-90">Win Rate</div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* League B Records */}
      {activeTab === 'leagueB' && (
        <div className="bg-white rounded-lg shadow-lg overflow-hidden">
          <div className="px-6 py-4 bg-gradient-to-r from-green-500 to-green-600 text-white">
            <h2 className="text-xl font-semibold flex items-center">
              <Star className="w-5 h-5 mr-2" />
              League B - Best Records
            </h2>
            <p className="text-green-100 text-sm">Top performers in recreational League B games</p>
          </div>

          {leagueBRecords.length === 0 ? (
            <div className="p-8 text-center text-gray-500">
              <Trophy className="mx-auto h-12 w-12 text-gray-400 mb-4" />
              <p>No League B records yet</p>
              <p className="text-sm">Complete some League B games to appear on the leaderboard</p>
            </div>
          ) : (
            <div className="divide-y divide-gray-200">
              {leagueBRecords.map((record, index) => (
                <div key={record.id} className={`p-6 ${getRankColor(index)}`}>
                  <div className="flex items-center justify-between">
                    <div className="flex items-center space-x-4">
                      {getRankIcon(index)}
                      <div className="w-12 h-12 bg-gray-200 rounded-full flex items-center justify-center">
                        {record.profile_pic ? (
                          <img 
                            src={record.profile_pic} 
                            alt={record.username} 
                            className="w-12 h-12 rounded-full object-cover"
                          />
                        ) : (
                          <Users className="w-6 h-6 text-gray-400" />
                        )}
                      </div>
                      <div>
                        <h3 className="text-lg font-semibold">{record.username}</h3>
                        <div className="flex items-center space-x-4 text-sm opacity-90">
                          <span>{record.total_games} games</span>
                          <span>{record.wins}W - {record.losses}L - {record.ties}T</span>
                        </div>
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="text-2xl font-bold">{record.win_percentage}%</div>
                      <div className="text-sm opacity-90">Win Rate</div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Money Games Earnings */}
      {activeTab === 'earnings' && (
        <div className="bg-white rounded-lg shadow-lg overflow-hidden">
          <div className="px-6 py-4 bg-gradient-to-r from-yellow-500 to-yellow-600 text-white">
            <h2 className="text-xl font-semibold flex items-center">
              <DollarSign className="w-5 h-5 mr-2" />
              Money Games - Top Earners
            </h2>
            <p className="text-yellow-100 text-sm">Highest earning players from money games</p>
          </div>

          {earningsRecords.length === 0 ? (
            <div className="p-8 text-center text-gray-500">
              <DollarSign className="mx-auto h-12 w-12 text-gray-400 mb-4" />
              <p>No money game earnings yet</p>
              <p className="text-sm">Participate in money games to appear on the earnings leaderboard</p>
            </div>
          ) : (
            <div className="divide-y divide-gray-200">
              {earningsRecords.map((record, index) => (
                <div key={record.id} className={`p-6 ${getRankColor(index)}`}>
                  <div className="flex items-center justify-between">
                    <div className="flex items-center space-x-4">
                      {getRankIcon(index)}
                      <div className="w-12 h-12 bg-gray-200 rounded-full flex items-center justify-center">
                        {record.profile_pic ? (
                          <img 
                            src={record.profile_pic} 
                            alt={record.username} 
                            className="w-12 h-12 rounded-full object-cover"
                          />
                        ) : (
                          <Users className="w-6 h-6 text-gray-400" />
                        )}
                      </div>
                      <div>
                        <h3 className="text-lg font-semibold">{record.username}</h3>
                        <div className="flex items-center space-x-4 text-sm opacity-90">
                          <span>{record.money_games_played} money games</span>
                          <span>{record.win_percentage}% win rate</span>
                        </div>
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="text-2xl font-bold text-green-600">
                        ${record.total_earnings.toFixed(2)}
                      </div>
                      <div className="text-sm opacity-90">
                        Net: ${(record.total_earnings - record.total_losses).toFixed(2)}
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Refresh Button */}
      <div className="mt-8 text-center">
        <button
          onClick={fetchLeaderboardData}
          className="inline-flex items-center px-6 py-3 border border-transparent text-base font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
        >
          <TrendingUp className="w-5 h-5 mr-2" />
          Refresh Leaderboard
        </button>
      </div>
    </div>
  );
};

export default Leaderboard;
